const HmrIgnoredModuleTimeouts = new Map();
const HmrIgnoredModuleIds = new Set();
const cancelModuleHmrAvailability = (moduleId) => {
    const timneout = HmrIgnoredModuleTimeouts.get(moduleId);
    if (timneout) {
        clearTimeout(timneout);
        HmrIgnoredModuleTimeouts.delete(moduleId);
    }
};
export const disableModuleHmr = (moduleId) => {
    cancelModuleHmrAvailability(moduleId);
    HmrIgnoredModuleIds.add(moduleId);
};
export const scheduleModuleHmrAvailability = (moduleId) => {
    if (!HmrIgnoredModuleIds.has(moduleId))
        return;
    cancelModuleHmrAvailability(moduleId);
    HmrIgnoredModuleTimeouts.set(moduleId, setTimeout(() => {
        HmrIgnoredModuleIds.delete(moduleId);
        HmrIgnoredModuleTimeouts.delete(moduleId);
    }, 500));
    return [];
};
